def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]
    prefix_length = len(prefix)
    suffix_length = len(suffix)
    # Find the start index to check for matches
    for i in range(len(s) - prefix_length - suffix_length + 1):
        if s[i:i + prefix_length] == prefix:
            if s[i + prefix_length:i + prefix_length + suffix_length] == suffix:
                # We found the exact prefix and suffix match
                return True
            # Check if there is a match with any sequence in between
            if s[i + prefix_length:].startswith(suffix):
                return True
    return False

