def sumOfGoodNumbers(nums: List[int], k: int) -> int:
    total = 0
    n = len(nums)
    for i in range(n):
        is_good = True
        if i - k >= 0 and nums[i] <= nums[i - k]:
            is_good = False
        if i + k < n and nums[i] <= nums[i + k]:
            is_good = False
        if is_good:
            total += nums[i]
    return total

def hasSpecialSubstring(s: str, k: int) -> bool:
    n = len(s)
    # Iterate through the string to find substrings of length k
    for i in range(n - k + 1):
        substring = s[i:i + k]
        # Check if the substring has one distinct character
        if len(set(substring)) == 1:
            # Check the characters before and after the substring
            before = s[i - 1] if i > 0 else None
            after = s[i + k] if i + k < n else None
            if (before is None or before != substring[0]) and (after is None or after != substring[0]):
                return True
    return False

def hasSameDigits(s: str) -> bool:
    while len(s) > 2:
        s = ''.join(str((int(s[i]) + int(s[i + 1])) % 10) for i in range(len(s) - 1))
    return s[0] == s[1]

