from itertools import permutations

def totalNumbers(digits: List[int]) -> int:
    distinct_numbers = set()
    for perm in permutations(digits, 3):
        if perm[0] != 0 and perm[2] % 2 == 0:
            distinct_numbers.add(perm)
    return len(distinct_numbers)

def calculateScore(s: str) -> int:
    score = 0
    marked = [False] * len(s)
    mirror = {chr(i): chr(219 - i) for i in range(97, 123)}  # Mapping a-z to z-a

    for i in range(len(s)):
        if marked[i]:
            continue
        for j in range(i - 1, -1, -1):
            if not marked[j] and s[j] == mirror[s[i]]:
                marked[i] = marked[j] = True
                score += i - j
                break
    return score

