def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[-float('inf')] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = 0

    for i in range(m):
        for j in range(n):
            current_coins = coins[i][j]
            for k in range(3):  # k = 0, 1, 2 for neutralizations
                if i > 0:
                    if current_coins >= 0:
                        dp[i][j] = max(dp[i][j], dp[i - 1][j] + current_coins)
                    elif k > 0:
                        dp[i][j] = max(dp[i][j], dp[i - 1][j] + current_coins + abs(current_coins))
                if j > 0:
                    if current_coins >= 0:
                        dp[i][j] = max(dp[i][j], dp[i][j - 1] + current_coins)
                    elif k > 0:
                        dp[i][j] = max(dp[i][j], dp[i][j - 1] + current_coins + abs(current_coins))

    return dp[m - 1][n - 1]

