def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0] * 3 for _ in range(n)]

    # Initialize the first house costs
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill the dp table for all houses
    for i in range(1, n):
        for color in range(3):
            dp[i][color] = cost[i][color] + min(dp[i - 1][(color + 1) % 3], dp[i - 1][(color + 2) % 3])

    # Calculate the minimum cost while considering equidistant houses
    min_cost = float('inf')
    for color in range(3):
        for prev_color in range(3):
            if prev_color != color:
                min_cost = min(min_cost, dp[n - 1][color] + dp[n - 2][prev_color])

    return min_cost

from typing import List


def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in events:
        event_type = event[0]
        timestamp = int(event[1])

        # Process offline users that might come online
        for user_id in range(numberOfUsers):
            if not online_status[user_id] and timestamp >= offline_until[user_id]:
                online_status[user_id] = True

        if event_type == "OFFLINE":
            user_id = int(event[2])
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            mentions_string = event[2].strip()
            if mentions_string == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == "HERE":
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                mentioned_users = mentions_string.split()
                for mention in mentioned_users:
                    user_id = int(mention[2:])
                    if online_status[user_id]:
                        mentions[user_id] += 1

    return mentions

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0
    for char in s:
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1
        current_distance = abs(x) + abs(y)
        max_distance = max(max_distance, current_distance)

    # Maximum distance can be enhanced by k changes. Hence, total distance is computed as:
    return max_distance + k
